<?php
use App\Core\Db; require_once __DIR__.'/_common.php';
$pdo=Db::pdo(); $id=isset($_GET['id'])?(int)$_GET['id']:0;
$st=$pdo->prepare("SELECT * FROM cpms_approval_documents WHERE id=:id");$st->execute(array(':id'=>$id));$d=$st->fetch();
$st=$pdo->prepare("SELECT * FROM cpms_approval_lines WHERE document_id=:id ORDER BY line_order");$st->execute(array(':id'=>$id));$lines=$st->fetchAll();
$st=$pdo->prepare("SELECT * FROM cpms_approval_files WHERE document_id=:id ORDER BY id");$st->execute(array(':id'=>$id));$files=$st->fetchAll();
$content=approval_parse_content($d['content']);
?><!doctype html><html><head><meta charset="utf-8"><style>body{font-family:sans-serif;background:#f3f4f6}.paper{max-width:210mm;min-height:297mm;margin:20px auto;background:#fff;padding:20px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:6px}.noprint{margin:10px auto;max-width:210mm}@media print{.noprint{display:none}body{background:#fff}.paper{margin:0;box-shadow:none}}</style></head><body><div class="noprint"><button onclick="window.print()">인쇄</button></div><div class="paper"><h2><?php echo h($d['title']);?></h2><table><tr><th>역할</th><th>결재자</th><th>상태</th><th>승인일시</th></tr><?php foreach($lines as $l){?><tr><td><?php echo h($l['role_type']);?></td><td><?php echo h($l['approver_name']);?></td><td><?php echo h($l['line_status']);?></td><td><?php echo h($l['acted_at']);?></td></tr><?php }?></table><h3>문서내용</h3><table><?php foreach($content as $k=>$v){?><tr><th><?php echo h($k);?></th><td><?php echo nl2br(h($v));?></td></tr><?php }?></table><h3>첨부파일</h3><ul><?php foreach($files as $f){?><li><?php echo h($f['original_name']);?></li><?php }?></ul><?php if($d['doc_status']==='REJECTED'){?><div style="color:#b91c1c;border:1px solid #fecaca;padding:8px">반려단계: <?php echo h($d['rejected_step']);?> / 반려사유: <?php echo h($d['reject_reason']);?></div><?php }?></div></body></html>